import{_ as s,o,c as n,a2 as a}from"./chunks/framework.DZhUhjDB.js";const m=JSON.parse('{"title":"01 — Reconocimiento OSINT (Clásico, sin IA)","description":"01 — Reconocimiento OSINT (Clásico, sin IA)","frontmatter":{"title":"01 — Reconocimiento OSINT (Clásico, sin IA)","description":"01 — Reconocimiento OSINT (Clásico, sin IA)"},"headers":[],"relativePath":"modules/red-team/01-reconocimiento-osint.md","filePath":"modules/red-team/01-reconocimiento-osint.md","lastUpdated":1787529976000}'),i={name:"modules/red-team/01-reconocimiento-osint.md"};function t(l,e,r,c,p,d){return o(),n("div",null,[...e[0]||(e[0]=[a(`<h1 id="_01-—-reconocimiento-osint-clasico-sin-ia" tabindex="-1">01 — Reconocimiento OSINT (Clásico, sin IA)</h1><blockquote><p><strong>Objetivo del módulo:</strong> Dominar las técnicas clásicas de reconocimiento y OSINT técnico para mapear la superficie de ataque de un objetivo, sin usar IA, de forma sistemática, legal y reproducible.</p></blockquote><p>Este módulo es la <strong>puerta de entrada práctica</strong> a el Área 1. Aquí aprendes a descubrir <strong>qué existe</strong>, <strong>dónde está</strong> y <strong>cómo se ve</strong> un objetivo antes de pensar en explotar nada.</p><hr><h2 id="🎯-objetivos-de-aprendizaje" tabindex="-1">🎯 Objetivos de aprendizaje</h2><p>Al completar este módulo deberías ser capaz de:</p><ul><li>Explicar la diferencia entre <strong>OSINT general</strong> y <strong>reconocimiento técnico aplicado a pentesting</strong>.</li><li>Identificar el <strong>scope autorizado</strong> (dominios, rangos IP, assets en nube, subdominios).</li><li>Usar herramientas clásicas (whois, dig, Nmap, etc.) para: <ul><li>Resolver dominios, registrar DNS y obtener información de registros.</li><li>Descubrir hosts activos en un rango de red.</li><li>Enumerar puertos y servicios expuestos.</li></ul></li><li>Organizar tus hallazgos en un formato estructurado (tablas, notas, diagramas simples).</li><li>Generar un <strong>informe de reconocimiento</strong> claro y reutilizable para siguientes fases del pentest.</li></ul><hr><h2 id="📚-teoria-minima" tabindex="-1">📚 Teoría mínima</h2><p>Este módulo asume que te concentras en <strong>OSINT técnico y recon activo básico</strong> sobre objetivos autorizados.</p><h3 id="osint-vs-reconocimiento-tecnico" tabindex="-1">OSINT vs Reconocimiento técnico</h3><ul><li><p><strong>OSINT (Open Source Intelligence):</strong></p><ul><li>Información obtenida de fuentes públicas: buscadores, redes sociales, registros públicos, leaks, etc.</li><li>Puede incluir datos humanos (personas, roles), de negocio y técnicos.</li></ul></li><li><p><strong>Reconocimiento técnico aplicado a pentesting:</strong></p><ul><li>Se centra en la <strong>superficie técnica</strong>: dominios, subdominios, IPs, puertos, servicios, tecnologías visibles.</li><li>Incluye recon pasivo (sin tocar directamente al objetivo) y recon activo controlado (como Nmap) dentro del scope autorizado.</li></ul></li></ul><h3 id="fases-tipicas-de-recon" tabindex="-1">Fases típicas de recon</h3><ol><li><p><strong>Definición de scope</strong></p><ul><li>Qué dominios, subdominios, rangos de IP y aplicaciones están autorizados.</li><li>Qué está explícitamente fuera de alcance.</li></ul></li><li><p><strong>Reconocimiento pasivo</strong></p><ul><li>WHOIS, registros DNS, certificados (CRT), datos de OSINT general.</li><li>Sin enviar tráfico directo al objetivo (o lo mínimo posible).</li></ul></li><li><p><strong>Descubrimiento de hosts</strong></p><ul><li>Identificar qué IPs están activas dentro del rango autorizado.</li></ul></li><li><p><strong>Enumeración de puertos y servicios</strong></p><ul><li>Identificar qué puertos están abiertos y qué servicios parecen correr allí.</li></ul></li><li><p><strong>Organización de hallazgos</strong></p><ul><li>Tablas por host, servicio, versión y posibles vectores de ataque a investigar.</li></ul></li></ol><hr><h2 id="🗂-estructura-del-modulo" tabindex="-1">🗂 Estructura del módulo</h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>01-reconocimiento-osint/</span></span>
<span class="line"><span>├── teoria/</span></span>
<span class="line"><span>│   └── 01-fundamentos-osint.md   ← Conceptos base, metodología, fases</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── herramientas/</span></span>
<span class="line"><span>│   ├── whois/                    ← Uso básico + ejemplos</span></span>
<span class="line"><span>│   ├── dig-dns/                  ← Consultas DNS típicas</span></span>
<span class="line"><span>│   ├── nmap/                     ← Escaneos host discovery + puertos</span></span>
<span class="line"><span>│   └── otros/                    ← Otras herramientas de apoyo</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── tecnicas/</span></span>
<span class="line"><span>│   ├── 01-definir-scope.md          ← Cómo delimitar scope de forma profesional</span></span>
<span class="line"><span>│   ├── 02-recon-pasivo-dns-whois.md ← Procedimiento paso a paso</span></span>
<span class="line"><span>│   ├── 03-host-discovery-nmap.md    ← Descubrimiento de hosts</span></span>
<span class="line"><span>│   └── 04-enumeracion-puertos.md    ← Puertos/servicios básicos</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── laboratorios/</span></span>
<span class="line"><span>│   ├── lab-01-mapeo-superficie-basico/</span></span>
<span class="line"><span>│   │   ├── enunciado.md           ← Planteamiento del lab</span></span>
<span class="line"><span>│   │   ├── guia-paso-a-paso.md    ← Opcional, solo si se necesita apoyo</span></span>
<span class="line"><span>│   │   └── entregables.md         ← Qué debe producir el estudiante</span></span>
<span class="line"><span>│   └── (futuros labs...)</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└── portafolio/</span></span>
<span class="line"><span>    └── TEMPLATE-informe-recon.md  ← Plantilla de informe de reconocimiento</span></span></code></pre></div><blockquote><p>Todos los labs utilizarán una <strong>empresa ficticia</strong> y entornos controlados (rango de IPs de laboratorio, dominios simulados, etc.). Nunca se practicarán técnicas sobre objetivos reales sin autorización.</p></blockquote><hr><h2 id="📂-tipos-de-entregables-del-modulo" tabindex="-1">📂 Tipos de entregables del módulo</h2><p>En este módulo se esperan entregables clásicos de recon, por ejemplo:</p><ul><li><p><strong><code>informe-recon-inicial.md</code></strong></p><ul><li>Resumen del objetivo, scope, metodología y hallazgos clave.</li></ul></li><li><p><strong>Tablas de hosts y servicios</strong></p><ul><li>Host/IP, puertos abiertos, servicios detectados, notas.</li></ul></li><li><p><strong>Notas técnicas de comandos</strong></p><ul><li>Colección de comandos usados (whois, dig, Nmap) con comentarios.</li></ul></li><li><p><strong>Diagrama simple de superficie de ataque</strong> (opcional)</p><ul><li>Puede ser un esquema en texto o una imagen sencilla mostrando hosts y servicios principales.</li></ul></li></ul><p>Estos entregables se podrán luego enlazar desde <code>PORTAFOLIO.md</code> como evidencia de habilidades de reconocimiento.</p><hr><h2 id="🔗-encaje-del-modulo-en-el-area-y-la-ruta" tabindex="-1">🔗 Encaje del módulo en el área y la ruta</h2><p>Dentro de el Área 1, este módulo es el <strong>primer paso</strong> de la ruta ofensiva:</p><ol><li><code>01-reconocimiento-osint/</code> ← Este módulo (recon clásico)</li><li><code>02-pentesting-red-team/</code> ← Ciclo completo de pentest sobre labs</li><li><code>03-analisis-vulnerabilidades/</code></li><li><code>04-explotacion-web/</code> y <code>05-post-explotacion/</code></li><li>Otros módulos ofensivos (forense, ingeniería social, criptografía)</li></ol><p>También alimenta directamente:</p><ul><li>Rutas de <strong>Pentester / Red Team</strong>.</li><li>Rutas de <strong>Analista SOC / Blue Team</strong>, que necesitan entender qué se expone.</li><li>Área 3, donde más adelante podrás automatizar parte de este recon con IA, pero sobre una base clásica sólida.</li></ul><hr><h2 id="✅-proximos-pasos-dentro-de-este-modulo" tabindex="-1">✅ Próximos pasos dentro de este módulo</h2><p>Los siguientes pasos naturales serán:</p><ul><li>Crear <code>teoria/01-fundamentos-osint.md</code> con la teoría resumida que soporte estas prácticas.</li><li>Definir el <strong>Lab 01 — Mapeo de superficie básico</strong> en <code>laboratorios/lab-01-mapeo-superficie-basico/</code>.</li><li>Crear <code>portafolio/TEMPLATE-informe-recon.md</code> para unificar cómo presentas tus hallazgos.</li></ul><p>Con eso, el módulo quedará listo para empezar a añadir ejercicios concretos y ejemplos de alta calidad para tu portafolio.</p>`,34)])])}const g=s(i,[["render",t]]);export{m as __pageData,g as default};
